import{_ as e,o as a,c as o,a2 as s}from"./chunks/framework.Cz0TtJv6.js";const g=JSON.parse('{"title":"How the bot works","description":"The full DLMM Bot pipeline for newcomers — scan, vet, enter, manage, exit — plus the three sleeves and follow mode.","frontmatter":{"title":"How the bot works","description":"The full DLMM Bot pipeline for newcomers — scan, vet, enter, manage, exit — plus the three sleeves and follow mode."},"headers":[],"relativePath":"how-it-works.md","filePath":"how-it-works.md","lastUpdated":1786714422000}'),r={name:"how-it-works.md"};function n(l,t,i,d,h,p){return a(),o("div",null,[...t[0]||(t[0]=[s(`<h1 id="how-the-bot-works" tabindex="-1">How the bot works <a class="header-anchor" href="#how-the-bot-works" aria-label="Permalink to &quot;How the bot works&quot;">​</a></h1><p>An automated LP bot for <a href="https://meteora.ag" target="_blank" rel="noreferrer">Meteora DLMM</a> on Solana: <strong>park SOL in bins just under a hot token’s price, earn a fee when traders move through, cash back to SOL by fixed rules.</strong></p><p>Like a stall under the current price: shoppers walk through the bins, we collect a tiny fee, and we leave when the rules say leave.</p><p class="note warn">Memecoin LP can wipe a wallet. Burner only. See <a href="./risk">Risk &amp; sizing</a>.</p><h2 id="the-pipeline" tabindex="-1">The pipeline <a class="header-anchor" href="#the-pipeline" aria-label="Permalink to &quot;The pipeline&quot;">​</a></h2><p>Everything runs from one tick loop:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scan → vet → enter → manage → exit</span></span>
<span class="line"><span>  ↑                              │</span></span>
<span class="line"><span>  └──────── capital rotates ─────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Stage</th><th>What happens</th><th>How often</th></tr></thead><tbody><tr><td><strong>Scan</strong></td><td>Sweep Meteora’s pool list for busy SOL-quoted pools; dedupe copycat tickers; hard pool gates; score 0–100</td><td>Every 60s</td></tr><tr><td><strong>Vet</strong></td><td>On-chain + RugCheck: authorities, holders, insider clusters, creator rug history, age</td><td>At entry time</td></tr><tr><td><strong>Enter</strong></td><td>One-sided SOL below price (BidAsk for memes, Spot for majors), Kelly + score, rent budgets</td><td>Slot free + candidate passed</td></tr><tr><td><strong>Manage</strong></td><td>P0→P5 ladder: safety, stop, rotation, take-profit, fee claims, below-range</td><td>Every 15s</td></tr><tr><td><strong>Exit</strong></td><td>Close, swap leftovers to SOL (Zap SDK, Jupiter fallback), record measured PnL</td><td>When a rule fires</td></tr></tbody></table><ul><li><strong>SOL is the unit of account.</strong> Wins and losses are wallet SOL in and out — not USD screenshots.</li><li><strong>Rules beat gut feel.</strong> Wherever a human would “ask the group,” the bot takes the more defensive branch.</li></ul><h2 id="why-one-sided-sol-below-price" tabindex="-1">Why one-sided SOL below price? <a class="header-anchor" href="#why-one-sided-sol-below-price" aria-label="Permalink to &quot;Why one-sided SOL below price?&quot;">​</a></h2><p>The default entry never buys the token up front. Only SOL, in bins <strong>below</strong> the current price:</p><ol><li>Price <strong>dips</strong> into the range → bins buy tokens cheaper each step.</li><li>Price <strong>recovers</strong> through the range → those bins sell above acquisition, plus fees both ways.</li><li>Price <strong>never visits</strong> → SOL sits untouched: no profit, no loss (idle capital + a little rent).</li></ol><p>The bot waits for price to come to it. It is not guessing the top.</p><h2 id="the-three-sleeves" tabindex="-1">The three sleeves <a class="header-anchor" href="#the-three-sleeves" aria-label="Permalink to &quot;The three sleeves&quot;">​</a></h2><p>Sleeve is stamped at entry and decides range shape, sizing, and manage rules.</p><table tabindex="0"><thead><tr><th>Sleeve</th><th>What it trades</th><th>Range shape</th><th>Sizing (current defaults)</th></tr></thead><tbody><tr><td><strong>micro</strong></td><td>Young/small memes, mcap $100k–$200k</td><td>BidAsk below price</td><td>0.5× Kelly, max 0.45 SOL, <strong>1</strong> slot, ≤5% of wallet</td></tr><tr><td><strong>meme</strong></td><td>Main book, mcap ≥ $200k</td><td>BidAsk below price</td><td>Kelly × score multiplier</td></tr><tr><td><strong>majors</strong></td><td>Allowlisted SOL-quoted alts (PUMP, JTO, BONK, WIF, RAY, JUP, …)</td><td><strong>Spot</strong> (12% below / 6% above)</td><td>Fixed 0.75 SOL, max 1 slot, slower manage</td></tr></tbody></table><p>Majors run <strong>after</strong> meme entries, and only when at least <code>meme_reserve_slots</code> (2) remain free. Stable pairs like SOL‑USDC are permanently out of scope.</p><h2 id="managing-a-position-the-p0→p5-ladder" tabindex="-1">Managing a position: the P0→P5 ladder <a class="header-anchor" href="#managing-a-position-the-p0→p5-ladder" aria-label="Permalink to &quot;Managing a position: the P0→P5 ladder&quot;">​</a></h2><p>Checked top-to-bottom every 15 seconds. <strong>First match wins.</strong></p><table tabindex="0"><thead><tr><th>Rule</th><th>Name</th><th>One-liner</th></tr></thead><tbody><tr><td><strong>P0</strong></td><td>Safety exit</td><td>Rug signals → close <em>now</em>, dump to SOL, blacklist token + creator</td></tr><tr><td><strong>P1</strong></td><td>Stop loss</td><td>Worth &lt; 75% of entry in SOL → close</td></tr><tr><td><strong>P2</strong></td><td>Rotation</td><td>Fees/volume went cold, or too old → free the slot</td></tr><tr><td><strong>P3</strong></td><td>Above range</td><td>Climbed out the top → take profit (or exit slowly if it never visited)</td></tr><tr><td><strong>P4</strong></td><td>In range</td><td>Claim/bank fees, maybe profit-lock a slice</td></tr><tr><td><strong>P5</strong></td><td>Below range</td><td>100% token after a short grace → close, swap, cool down</td></tr></tbody></table><p>Full thresholds: <a href="./strategy">Strategy reference</a>.</p><h2 id="follow-mode-careful-re-entry" tabindex="-1">Follow mode (careful re-entry) <a class="header-anchor" href="#follow-mode-careful-re-entry" aria-label="Permalink to &quot;Follow mode (careful re-entry)&quot;">​</a></h2><p>After a clean up-and-out close (P3), follow mode may re-enter — through picky gates. Unguarded chasing lost money in simulation:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P3 close ──arms──▶ wait for: hot volume (≥$100k/30m)</span></span>
<span class="line"><span>                          + 15% retrace from the peak</span></span>
<span class="line"><span>                          + fresh token vetting</span></span>
<span class="line"><span>                └──▶ open a tighter leg (30% deep, 0.25 SOL)</span></span>
<span class="line"><span>                └──▶ re-arm only after a NEW chain high (up-only)</span></span>
<span class="line"><span>                └──▶ chain ends on: any non-P3 close, 3 legs,</span></span>
<span class="line"><span>                     −0.075 SOL cumulative loss, cold volume, or 12h</span></span></code></pre></div><p>While a follow chain owns a token, the normal scanner skips it. <a href="./strategy#p3-f-follow-mode">Strategy → Follow mode</a>.</p><h2 id="paper-vs-live" tabindex="-1">Paper vs live <a class="header-anchor" href="#paper-vs-live" aria-label="Permalink to &quot;Paper vs live&quot;">​</a></h2><ul><li><strong>Paper (default):</strong> full brain, real pool data, simulated fills. No wallet needed.</li><li><strong>Live:</strong> real SOL. Needs <strong>both</strong> <code>FARMER_MODE=live</code> <strong>and</strong> <code>[exec] mode = &quot;live&quot;</code>. One switch stays paper.</li></ul><p>Promotion gate: <code>npm run status</code> marks <strong>eligible</strong> after 7 consecutive profitable paper days. <a href="./risk#paper-first-the-promotion-gate">Risk → Paper first</a>.</p><h2 id="what-s-actually-running" tabindex="-1">What&#39;s actually running <a class="header-anchor" href="#what-s-actually-running" aria-label="Permalink to &quot;What&#39;s actually running&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Process</th><th>Job</th></tr></thead><tbody><tr><td><strong>Farmer</strong></td><td>Tick loop — scans, vets, opens, manages, closes.</td></tr><tr><td><strong>Dashboard</strong></td><td>Positions, charts, HALT, settings, Wiki.</td></tr><tr><td><strong>Deploy watcher</strong> (optional)</td><td>Pulls new builds from GitHub.</td></tr><tr><td><strong>SQLite + config</strong></td><td><code>data/farmer.db</code> and <code>data/config.toml</code> (hot-reloaded).</td></tr></tbody></table><p>On every startup the bot enumerates on-chain DLMM positions and repairs the DB to match. The chain wins.</p><p class="cta-row"><a class="doc-btn ghost" href="./strategy">Strategy</a><a class="doc-btn ghost" href="./risk">Risk &amp; sizing</a><a class="doc-btn ghost" href="./easy">Easy setup</a></p>`,32)])])}const u=e(r,[["render",n]]);export{g as __pageData,u as default};
